<script>
   window.cartData = [];
   var totsterMsgTimeInSec = '3000';
   var callAjaxAfterMsInSec = '500';
   jQuery(function() {
        function updateAlertPosition() {
            const mshServicesElement = jQuery('.msh-services.visible-xs'); 
            const msAccountElement = jQuery('.ms-account'); 
            const wrapperElement = jQuery('.alert-wrapper');     
            if (wrapperElement.length === 0) {
                return;
            }
            const isMshServicesVisible = mshServicesElement.length > 0 && mshServicesElement[0].getBoundingClientRect().bottom > 0;
            const isMsAccountVisible = msAccountElement.length > 0 && msAccountElement[0].getBoundingClientRect().bottom > 0;

            if (isMshServicesVisible || isMsAccountVisible) {
                wrapperElement.css('top', '190px');
            } else {
                wrapperElement.css('top', '10px');
            }
        }

        jQuery(window).on('scroll resize', updateAlertPosition);
        updateAlertPosition();
    });
</script><script>
